/**
 * Generated by out/nivo/tools/reels.py from registry/snap-cn-pro/templates/<slug>
 * (gitignored, so the public site cannot import it). Films live on R2 at
 * `templates-wip/<slug>-<v>.mp4` and `<slug>-<k>-<still>.webp` (hashes in the names).
 */
export type Reel = {
  slug: string;
  /** Registry item: `npx shadcn add @snapcn/<install>`. */
  install: string;
  title: string;
  description: string;
  fps: number;
  /** The film at 3840x2160: `<slug>-<v>.mp4`. */
  v: string;
  /** The same film at 1920x1080, for small screens: `<slug>-1080-<v1080>.mp4`. */
  v1080: string;
  /** Hashes of `<slug>-1/2/3.webp`, three stills across the film. */
  stills: readonly string[];
  beats: readonly { label: string; component: string; frames: number }[];
};

